228: // ================= AUTHENTICATION HANDLERS =================
229: function checkActiveSession() {
230:     const savedRole = localStorage.getItem('ims_role');
231:     if (savedRole && (savedRole === 'admin' || savedRole === 'staff')) {
232:         loginUser(savedRole);
233:     } else {
234:         // Show login screen
235:         DOM.loginOverlay.style.display = 'flex';
236:         DOM.appWrapper.style.display = 'none';
237:     }
238: }
