240: function handleLoginSubmit(e) {
241:     e.preventDefault();
242:     const username = DOM.loginUsername.value.trim().toLowerCase();
243:     const password = DOM.loginPassword.value.trim();
244: 
245:     // Check credentials against dynamic state keys
246:     const adminPass = state.adminPassword || 'ims';
247:     const staffPass = state.staffPassword || 'ims';
248: 
249:     if (username === 'admin' && password === adminPass) {
250:         loginUser('admin');
251:     } else if (username === 'staff' && password === staffPass) {
252:         loginUser('staff');
253:     } else {
254:         alert(`Invalid credentials. Try: \nAdmin: admin / ${adminPass === 'ims' ? 'ims' : 'custom_password'} \nStaff: staff / ${staffPass === 'ims' ? 'ims' : 'custom_password'}`);
255:     }
256: }
