258: function loginUser(role) {
259:     state.role = role;
260:     state.isAdmin = (role === 'admin');
261:     localStorage.setItem('ims_role', role);
262: 
263:     // Hide Login Overlay, Show App
264:     DOM.loginOverlay.style.display = 'none';
265:     DOM.appWrapper.style.display = 'flex';
266: 
267:     // Update Header active role badge styling
268:     const badge = DOM.roleDisplayBadge;
269:     badge.textContent = `${role} view`;
270:     if (role === 'admin') {
271:         badge.className = 'role-badge';
272:     } else {
273:         badge.className = 'role-badge role-staff';
274:     }
275: 
276:     applyPrivilegeRestrictions();
277: 
278:     // Auto-seed if database is empty on first startup
279:     if (state.assets.length === 0 && state.vendors.length === 0) {
280:         seedDemoData(false);
281:     } else {
282:         renderAll();
283:     }
284: }
