286: function logoutUser() {
287:     state.role = 'guest';
288:     state.isAdmin = false;
289:     localStorage.removeItem('ims_role');
290:     
291:     // Clear login forms
292:     DOM.loginUsername.value = '';
293:     DOM.loginPassword.value = '';
294: 
295:     DOM.loginOverlay.style.display = 'flex';
296:     DOM.appWrapper.style.display = 'none';
