303:     adminElements.forEach(el => {
304:         if (state.isAdmin) {
305:             el.classList.remove('staff-restricted');
306:         } else {
307:             el.classList.add('staff-restricted');
308:         }
309:     });
310: 
311:     // Handle Logs Nav Tab visibility
312:     const logsTabBtn = document.querySelector('.tab-btn[data-tab="logs-tab"]');
313:     if (logsTabBtn) {
314:         if (state.isAdmin) {
315:             logsTabBtn.style.display = 'flex';
