500: function toggleTheme() {
501:     const nextTheme = state.theme === 'dark' ? 'light' : 'dark';
502:     state.theme = nextTheme;
503:     document.documentElement.setAttribute('data-theme', nextTheme);
504:     localStorage.setItem('ims_theme', nextTheme);
505:     updateThemeIcon(nextTheme);
506:     renderDashboardCharts();
