517: // ================= FILE UPLOAD CONTROLLERS =================
518: function handleFileUpload(e, type) {
519:     const file = e.target.files[0];
520:     if (!file) return;
521: 
522:     // Constrain file size (Base64 sizes shouldn't bloat local storage beyond 5MB total)
523:     if (file.size > 800000) {
524:         alert("Attached file size exceeds 800KB. To preserve local storage space, upload smaller images or documents.");
525:         e.target.value = '';
526:         return;
527:     }
528: 
529:     const reader = new FileReader();
530:     reader.onload = function(evt) {
531:         const base64 = evt.target.result;
532:         if (type === 'photo') {
533:             tempAttachedPhoto = base64;
534:             DOM.photoFileStatus.textContent = "Attached ✓";
535:             DOM.photoFileStatus.style.color = "var(--color-success)";
536:         } else {
537:             tempAttachedInvoice = base64;
538:             DOM.invoiceFileStatus.textContent = "Attached ✓";
539:             DOM.invoiceFileStatus.style.color = "var(--color-success)";
540:         }
541:     };
542:     reader.readAsDataURL(file);
543: }
