1065:         { el: DOM.thName, name: 'Asset Name' },
1066:         { el: DOM.thCategory, name: 'Category' },
1067:         { el: DOM.thStatus, name: 'Status' }
1068:     ];
1069: 
1070:     headers.forEach(h => {
1071:         if (!h.el) return;
1072:         let suffix = '\u00A0⇅';
1073:         if (h.el.id.includes(column)) {
1074:             suffix = sortConfig.direction === 'asc' ? '\u00A0▲' : '\u00A0▼';
1075:         }
1076:         h.el.textContent = h.name + suffix;
1077:     });
1078: 
