1082: function sortAssets(assetsList) {
1083:     const col = sortConfig.column;
1084:     const dir = sortConfig.direction;
1085: 
1086:     return [...assetsList].sort((a, b) => {
1087:         let valA = a[col] || '';
1088:         let valB = b[col] || '';
1089: 
1090:         if (typeof valA === 'string') valA = valA.toLowerCase();
1091:         if (typeof valB === 'string') valB = valB.toLowerCase();
1092: 
1093:         if (valA < valB) return dir === 'asc' ? -1 : 1;
1094:         if (valA > valB) return dir === 'asc' ? 1 : -1;
1095:         return 0;
1096:     });
1097: }
