1102:     container.innerHTML = '';
1103: 
1104:     const currentPage = paginationConfig.currentPage;
1105:     const maxVisible = 5; // Max page buttons to display
1106:     
1107:     let startPage = Math.max(1, currentPage - Math.floor(maxVisible / 2));
1108:     let endPage = Math.min(totalPages, startPage + maxVisible - 1);
1109:     
1110:     if (endPage - startPage + 1 < maxVisible) {
1111:         startPage = Math.max(1, endPage - maxVisible + 1);
1112:     }
1113: 
1114:     if (startPage > 1) {
1115:         createPageButton(1);
1116:         if (startPage > 2) {
1117:             createEllipsis();
1118:         }
1119:     }
1120: 
1121:     for (let i = startPage; i <= endPage; i++) {
1122:         createPageButton(i);
1123:     }
1124: 
1125:     if (endPage < totalPages) {
1126:         if (endPage < totalPages - 1) {
1127:             createEllipsis();
1128:         }
1129:         createPageButton(totalPages);
1130:     }
1131: 
1132:     function createPageButton(pageNum) {
1133:         const btn = document.createElement('button');
1134:         btn.className = 'btn-page-num';
1135:         if (pageNum === currentPage) {
1136:             btn.classList.add('active');
1137:         }
1138:         btn.textContent = pageNum;
1139:         btn.addEventListener('click', () => {
1140:             paginationConfig.currentPage = pageNum;
1141:             renderInventoryTable();
1142:         });
1143:         container.appendChild(btn);
1144:     }
1145: 
1146:     function createEllipsis() {
1147:         const span = document.createElement('span');
1148:         span.style.color = 'var(--text-muted)';
1149:         span.style.fontSize = '13px';
1150:         span.style.padding = '0 4px';
1151:         span.style.display = 'inline-flex';
1152:         span.style.alignItems = 'center';
1153:         span.textContent = '...';
1154:         container.appendChild(span);
1155:     }
1156: }
