1158: // ================= INVENTORY TABLE CONTROLLER =================
1159: function renderInventoryTable() {
1160:     const tableBody = DOM.inventoryTableBody;
1161:     const query = DOM.inventorySearch.value.trim().toLowerCase();
1162:     const catFilter = DOM.filterCategory.value;
1163:     const statFilter = DOM.filterStatus.value;
1164: 
1165:     tableBody.innerHTML = '';
1166: 
1167:     let filtered = state.assets.filter(asset => {
1168:         if (catFilter !== 'all' && asset.category !== catFilter) return false;
1169:         if (statFilter !== 'all' && asset.status !== statFilter) return false;
1170: 
1171:         if (query) {
1172:             const nameMatch = asset.name.toLowerCase().includes(query);
1173:             const tagMatch = asset.tag.toLowerCase().includes(query);
1174:             const skuMatch = (asset.model || '').toLowerCase().includes(query);
1175:             const brandMatch = (asset.brand || '').toLowerCase().includes(query);
1176:             const userMatch = (asset.assignedUser || '').toLowerCase().includes(query);
1177:             const serialMatch = (asset.serial || '').toLowerCase().includes(query);
1178: 
1179:             return nameMatch || tagMatch || skuMatch || brandMatch || userMatch || serialMatch;
1180:         }
1181:         return true;
1182:     });
1183: 
1184:     filtered = sortAssets(filtered);
1185: 
1186:     if (filtered.length === 0) {
1187:         DOM.inventoryEmptyState.style.display = 'flex';
1188:         if (DOM.inventoryPagination) DOM.inventoryPagination.style.display = 'none';
1189:         return;
1190:     } else {
1191:         DOM.inventoryEmptyState.style.display = 'none';
1192:         if (DOM.inventoryPagination) DOM.inventoryPagination.style.display = 'flex';
1193:     }
1194: 
1195:     // Pagination calculations
1196:     const totalItems = filtered.length;
1197:     const totalPages = Math.ceil(totalItems / paginationConfig.pageSize);
1198: 
1199:     // Clamp current page to valid bounds
1200:     if (paginationConfig.currentPage > totalPages && totalPages > 0) {
1201:         paginationConfig.currentPage = totalPages;
1202:     }
1203:     if (paginationConfig.currentPage < 1) {
1204:         paginationConfig.currentPage = 1;
1205:     }
1206: 
1207:     const startIdx = (paginationConfig.currentPage - 1) * paginationConfig.pageSize;
1208:     const endIdx = Math.min(startIdx + paginationConfig.pageSize, totalItems);
1209: 
1210:     // Render page status text
1211:     if (DOM.paginationInfo) {
1212:         DOM.paginationInfo.textContent = `Showing ${totalItems > 0 ? startIdx + 1 : 0}-${endIdx} of ${totalItems} assets`;
1213:     }
1214: 
1215:     // Enable/disable page prev/next buttons
1216:     if (DOM.btnPagePrev) DOM.btnPagePrev.disabled = (paginationConfig.currentPage === 1);
1217:     if (DOM.btnPageNext) DOM.btnPageNext.disabled = (paginationConfig.currentPage === totalPages || totalPages === 0);
1218: 
1219:     // Render numbered page buttons
1220:     renderPaginationControls(totalPages);
1221: 
1222:     // Slice assets for current page
1223:     const pageAssets = filtered.slice(startIdx, endIdx);
1224: 
1225:     pageAssets.forEach(asset => {
1226:         const tr = document.createElement('tr');
1227:         tr.style.cursor = 'pointer';
1228:         
1229:         tr.addEventListener('click', (e) => {
1230:             if (e.target.closest('.action-prevent-drawer')) return;
1231:             openDrawer(asset.id);
1232:         });
1233: 
1234:         const statusClass = `status-${asset.status.toLowerCase()}`;
1235:         const userDisplay = asset.status === 'Assigned' 
1236:             ? `<div style="font-weight: 600;">${asset.assignedUser}</div><div style="font-size:11px; color:var(--text-muted);">${asset.department}</div>`
1237:             : `<span style="color: var(--text-muted);">Unassigned</span>`;
1238: 
1239:         // Fetch hardware upgrades/replacements
1240:         const assetUpgrades = state.maintenance.filter(m => m.assetId === asset.id);
1241:         const upgradesText = assetUpgrades.length > 0 
1242:             ? assetUpgrades.map(u => `${u.partReplaced} (${u.status || 'Completed'})`).join(', ')
1243:             : `<span style="color:var(--text-muted); font-size:12px;">None</span>`;
1244: 
1245:         // Render actions column depending on role
1246:         let actionsHtml = "";
1247:         if (state.isAdmin) {
1248:             actionsHtml = `
1249:                 ${asset.status === 'Available' ? `
1250:                     <button class="btn btn-primary btn-sm" onclick="openAssignModal('${asset.id}')">Assign</button>
1251:                 ` : ''}
1252:                 ${asset.status === 'Assigned' ? `
1253:                     <button class="btn btn-secondary btn-sm" onclick="returnAsset('${asset.id}')">Return</button>
1254:                 ` : ''}
1255:             `;
1256:         }
1257: 
1258:         tr.innerHTML = `
1259:             <td><span class="asset-tag-pill">${asset.tag}</span></td>
1260:             <td>
1261:                 <div style="font-weight:600; color:var(--text-primary);">${asset.name}</div>
1262:                 <div style="font-size:12px; color:var(--text-secondary);">${asset.brand || '-'} ${asset.model || ''}</div>
1263:             </td>
1264:             <td style="color:var(--text-secondary); font-size:13.5px;">${asset.category}</td>
1265:             <td style="font-size:12px; color:var(--text-muted); max-width:260px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${asset.specs || 'None'}">
1266:                 ${asset.specs || 'N/A'}
1267:             </td>
1268:             <td>
1269:                 <span class="status-badge ${statusClass}">${asset.status}</span>
1270:             </td>
1271:             <td>${userDisplay}</td>
1272:             <td style="font-size:12px; color:var(--text-secondary); max-width:180px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${assetUpgrades.map(u => `${u.partReplaced} (${u.status || 'Completed'})`).join(', ')}">
1273:                 ${upgradesText}
1274:             </td>
1275:             <td style="text-align: right;" class="action-prevent-drawer">
1276:                 <div style="display:flex; justify-content:flex-end; gap:6px;">
1277:                     ${actionsHtml}
1278:                     <button class="btn btn-secondary btn-sm" style="padding: 5px 8px;" onclick="openDrawer('${asset.id}')">
1279:                         🔎
1280:                     </button>
1281:                 </div>
1282:             </td>
1283:         `;
1284:         tableBody.appendChild(tr);
1285:     });
1286: }
