1485: function deleteAsset(assetId) {
1486:     const index = state.assets.findIndex(a => a.id === assetId);
1487:     if (index === -1) return;
1488: 
1489:     const asset = state.assets[index];
1490:     if (confirm(`Are you absolutely sure you want to delete ${asset.name} (${asset.tag})? This action cannot be undone.`)) {
1491:         state.assets.splice(index, 1);
1492:         saveState();
1493:         logTransaction(
1494:             'Status Change',
1495:             asset.tag,
1496:             asset.name,
1497:             `Asset deleted / retired from IMS records.`
1498:         );
1499:         renderAll();
1500:     }
