2823: // ================= ROBUST INVOICE FILE OPENER =================
2824: window.openInvoice = function(invoiceBase64, assetTag) {
2825:     if (!invoiceBase64) return;
2826:     
2827:     try {
2828:         const parts = invoiceBase64.split(',');
2829:         if (parts.length < 2) return;
2830:         
2831:         const mimeMatch = parts[0].match(/:(.*?);/);
2832:         const mimeType = mimeMatch ? mimeMatch[1] : 'application/pdf';
2833:         
2834:         // Convert Base64 to Blob binary format
2835:         const byteCharacters = atob(parts[1]);
2836:         const byteNumbers = new Array(byteCharacters.length);
2837:         for (let i = 0; i < byteCharacters.length; i++) {
2838:             byteNumbers[i] = byteCharacters.charCodeAt(i);
2839:         }
2840:         const byteArray = new Uint8Array(byteNumbers);
2841:         const blob = new Blob([byteArray], { type: mimeType });
2842:         
2843:         // Generate Blob object URL
2844:         const fileURL = URL.createObjectURL(blob);
2845:         
2846:         let extension = 'pdf';
2847:         if (mimeType.includes('png')) extension = 'png';
2848:         else if (mimeType.includes('jpeg') || mimeType.includes('jpg')) extension = 'jpg';
2849:         else if (mimeType.includes('svg')) extension = 'svg';
2850: 
2851:         // Attempt to view in a new browser tab/window
2852:         const newWindow = window.open(fileURL, '_blank');
2853:         if (!newWindow) {
2854:             // Fallback download trigger if popup blocker intervenes
2855:             const link = document.createElement("a");
2856:             link.href = fileURL;
2857:             link.download = `IMS_Invoice_${assetTag}.${extension}`;
2858:             document.body.appendChild(link);
2859:             link.click();
2860:             document.body.removeChild(link);
2861:         }
2862:     } catch (err) {
2863:         console.error("Error opening invoice:", err);
2864:         alert("Failed to parse invoice file. Please try re-uploading.");
2865:     }
2866: };
