function renderDashboardAlerts() {
    const container = DOM.alertsContainer;
    container.innerHTML = '';

    const today = new Date();
    const alerts = [];

    state.assets.forEach(asset => {
        if (!asset.warrantyExpiry) return;
        const expDate = new Date(asset.warrantyExpiry);
        const diffTime = expDate - today;
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        if (diffDays < 0) {
            alerts.push({
                type: 'danger', // Critical priority
                asset: asset,
                message: `Warranty EXPIRED on ${asset.warrantyExpiry}`,
                badge: 'Critical'
            });
        } else if (diffDays <= 90) {
            alerts.push({
                type: 'warning', // Warning priority
                asset: asset,
                message: `Warranty expiring in ${diffDays} days (${asset.warrantyExpiry})`,
                badge: 'Warning'
            });
        }
    });

    state.assets.forEach(asset => {
        if (asset.status === 'Maintenance') {
            alerts.push({
                type: 'info', // Maintenance priority
                asset: asset,
                message: `Currently offline undergoing maintenance`,
                badge: 'Maintenance'
            });
        }
    });

    if (alerts.length === 0) {
        container.innerHTML = `
            <div class="empty-state">
                <div class="empty-state-icon">🛡️</div>
                <p style="font-size: 13px;">No critical notifications. All device warranties and maintenance pipelines are green.</p>
            </div>`;
        return;
    }

    // Sort alerts: danger first, then warning, then info
    alerts.sort((a, b) => {
        const order = { 'danger': 1, 'warning': 2, 'info': 3 };
        return order[a.type] - order[b.type];
    });

    alerts.forEach(alert => {
        const div = document.createElement('div');
        div.className = 'alert-item';
        div.style.cursor = 'pointer';
        div.style.flexDirection = 'column';
        div.style.alignItems = 'stretch';
        div.style.gap = '8px';
        div.addEventListener('click', () => openDrawer(alert.asset.id));

        let badgeClass = 'badge-expiring'; // critical
        if (alert.type === 'warning') badgeClass = 'badge-low';
        else if (alert.type === 'info') badgeClass = 'status-badge status-maintenance';

        let actionButtons = `<button class="btn btn-secondary btn-sm" style="padding: 3px 8px; font-size:11px;" onclick="event.stopPropagation(); openDrawer('${alert.asset.id}');">Manage</button>`;

        // Add extend warranty option for warranty alerts in admin view
        if (state.isAdmin && (alert.type === 'danger' || alert.type === 'warning')) {
            actionButtons += `
                <button class="btn btn-primary btn-sm" style="padding: 3px 8px; font-size:11px; margin-left:6px;" onclick="extendWarranty('${alert.asset.id}', event)">Extend Warranty</button>
            `;
        }

        div.innerHTML = `
            <div style="display:flex; justify-content:space-between; align-items:center; width:100%;">
                <div>
                    <strong style="color:var(--text-primary); font-size:13.5px;">${alert.asset.name}</strong>
                    <span class="asset-tag-pill" style="font-size: 10px; padding: 1px 4px; margin-left: 6px;">${alert.asset.tag}</span>
                </div>
                <span class="alert-badge ${badgeClass}" style="padding:1px 6px; font-size:10px;">${alert.badge}</span>
            </div>
            <div style="display:flex; justify-content:space-between; align-items:center; width:100%; border-top:1px dashed rgba(255,255,255,0.05); padding-top:6px; margin-top:2px;">
                <p style="font-size: 11.5px; color: var(--text-secondary); margin:0;">${alert.message}</p>
                <div style="display:flex; gap:4px;">
                    ${actionButtons}
                </div>
            </div>
        `;
        container.appendChild(div);
    });
}

