1189: // ================= SORT & TABLE HELPERS =================
1190: function handleSort(column) {
1191:     if (sortConfig.column === column) {
1192:         sortConfig.direction = sortConfig.direction === 'asc' ? 'desc' : 'asc';
1193:     } else {
1194:         sortConfig.column = column;
1195:         sortConfig.direction = 'asc';
1196:     }
1197: 
1198:     const headers = [
1199:         { el: DOM.thTag, name: 'Asset Tag' },
1200:         { el: DOM.thName, name: 'Asset Name' },
1201:         { el: DOM.thCategory, name: 'Category' },
1202:         { el: DOM.thStatus, name: 'Status' }
1203:     ];
1204: 
1205:     headers.forEach(h => {
1206:         if (!h.el) return;
1207:         let suffix = '\u00A0⇅';
1208:         if (h.el.id.includes(column)) {
1209:             suffix = sortConfig.direction === 'asc' ? '\u00A0▲' : '\u00A0▼';
1210:         }
1211:         h.el.textContent = h.name + suffix;
1212:     });
1213: 
1214:     renderInventoryTable();
1215: }
