1217: function sortAssets(assetsList) {
1218:     const col = sortConfig.column;
1219:     const dir = sortConfig.direction;
1220: 
1221:     return [...assetsList].sort((a, b) => {
1222:         let valA = a[col] || '';
1223:         let valB = b[col] || '';
1224: 
1225:         if (typeof valA === 'string') valA = valA.toLowerCase();
1226:         if (typeof valB === 'string') valB = valB.toLowerCase();
1227: 
1228:         if (valA < valB) return dir === 'asc' ? -1 : 1;
1229:         if (valA > valB) return dir === 'asc' ? 1 : -1;
1230:         return 0;
1231:     });
1232: }
