1238: 
1239:     const currentPage = paginationConfig.currentPage;
1240:     const maxVisible = 5; // Max page buttons to display
1241:     
1242:     let startPage = Math.max(1, currentPage - Math.floor(maxVisible / 2));
1243:     let endPage = Math.min(totalPages, startPage + maxVisible - 1);
1244:     
1245:     if (endPage - startPage + 1 < maxVisible) {
1246:         startPage = Math.max(1, endPage - maxVisible + 1);
1247:     }
1248: 
1249:     if (startPage > 1) {
1250:         createPageButton(1);
1251:         if (startPage > 2) {
1252:             createEllipsis();
