1254:     }
1255: 
1256:     for (let i = startPage; i <= endPage; i++) {
1257:         createPageButton(i);
1258:     }
1259: 
1260:     if (endPage < totalPages) {
1261:         if (endPage < totalPages - 1) {
1262:             createEllipsis();
1263:         }
1264:         createPageButton(totalPages);
1265:     }
