1293: // ================= INVENTORY TABLE CONTROLLER =================
1294: function renderInventoryTable() {
1295:     const tableBody = DOM.inventoryTableBody;
1296:     const query = DOM.inventorySearch.value.trim().toLowerCase();
1297:     const catFilter = DOM.filterCategory.value;
1298:     const statFilter = DOM.filterStatus.value;
1299: 
1300:     tableBody.innerHTML = '';
1301: 
1302:     let filtered = state.assets.filter(asset => {
1303:         if (catFilter !== 'all' && asset.category !== catFilter) return false;
1304:         if (statFilter !== 'all' && asset.status !== statFilter) return false;
1305: 
1306:         if (query) {
1307:             const nameMatch = asset.name.toLowerCase().includes(query);
1308:             const tagMatch = asset.tag.toLowerCase().includes(query);
1309:             const skuMatch = (asset.model || '').toLowerCase().includes(query);
1310:             const brandMatch = (asset.brand || '').toLowerCase().includes(query);
1311:             const userMatch = (asset.assignedUser || '').toLowerCase().includes(query);
1312:             const serialMatch = (asset.serial || '').toLowerCase().includes(query);
1313: 
1314:             return nameMatch || tagMatch || skuMatch || brandMatch || userMatch || serialMatch;
1315:         }
1316:         return true;
1317:     });
1318: 
1319:     filtered = sortAssets(filtered);
1320: 
1321:     if (filtered.length === 0) {
1322:         DOM.inventoryEmptyState.style.display = 'flex';
1323:         if (DOM.inventoryPagination) DOM.inventoryPagination.style.display = 'none';
1324:         return;
1325:     } else {
1326:         DOM.inventoryEmptyState.style.display = 'none';
1327:         if (DOM.inventoryPagination) DOM.inventoryPagination.style.display = 'flex';
1328:     }
1329: 
1330:     // Pagination calculations
1331:     const totalItems = filtered.length;
1332:     const totalPages = Math.ceil(totalItems / paginationConfig.pageSize);
1333: 
1334:     // Clamp current page to valid bounds
1335:     if (paginationConfig.currentPage > totalPages && totalPages > 0) {
1336:         paginationConfig.currentPage = totalPages;
1337:     }
1338:     if (paginationConfig.currentPage < 1) {
1339:         paginationConfig.currentPage = 1;
1340:     }
1341: 
1342:     const startIdx = (paginationConfig.currentPage - 1) * paginationConfig.pageSize;
1343:     const endIdx = Math.min(startIdx + paginationConfig.pageSize, totalItems);
1344: 
1345:     // Render page status text
1346:     if (DOM.paginationInfo) {
1347:         DOM.paginationInfo.textContent = `Showing ${totalItems > 0 ? startIdx + 1 : 0}-${endIdx} of ${totalItems} assets`;
1348:     }
1349: 
1350:     // Enable/disable page prev/next buttons
1351:     if (DOM.btnPagePrev) DOM.btnPagePrev.disabled = (paginationConfig.currentPage === 1);
1352:     if (DOM.btnPageNext) DOM.btnPageNext.disabled = (paginationConfig.currentPage === totalPages || totalPages === 0);
1353: 
1354:     // Render numbered page buttons
1355:     renderPaginationControls(totalPages);
1356: 
1357:     // Slice assets for current page
1358:     const pageAssets = filtered.slice(startIdx, endIdx);
1359: 
1360:     pageAssets.forEach(asset => {
1361:         const tr = document.createElement('tr');
1362:         tr.style.cursor = 'pointer';
1363:         
1364:         tr.addEventListener('click', (e) => {
1365:             if (e.target.closest('.action-prevent-drawer')) return;
1366:             openDrawer(asset.id);
1367:         });
1368: 
1369:         const statusClass = `status-${asset.status.toLowerCase()}`;
