1371:             ? `<div style="font-weight: 600;">${asset.assignedUser}</div><div style="font-size:11px; color:var(--text-muted);">${asset.department}</div>`
1372:             : `<span style="color: var(--text-muted);">Unassigned</span>`;
1373: 
1374:         // Fetch hardware upgrades/replacements
1375:         const assetUpgrades = state.maintenance.filter(m => m.assetId === asset.id);
1376:         const upgradesText = assetUpgrades.length > 0 
1377:             ? assetUpgrades.map(u => `${u.partReplaced} (${u.status || 'Completed'})`).join(', ')
1378:             : `<span style="color:var(--text-muted); font-size:12px;">None</span>`;
1379: 
